class Repo:
    def __init__(self, path):
        self.path = path
        self.config = {}
        self.commits = []
        self.staged = {}
        self.working = {}

    def set_config(self, key, value):
        self.config[key] = value

repo = Repo("my-project")
print(f"Initialized empty repository in {repo.path}/.git/")
repo.set_config("user.name", "Ada Lovelace")
repo.set_config("user.email", "ada@example.com")
for key in sorted(repo.config):
    print(f"{key}={repo.config[key]}")
print(f"commits: {len(repo.commits)}")
